// 本片数字由 scratchpad/v13.py 独立核算：
//   3000 个随机 MDP 全部 (s,a)：max[Q*(s,a) − V*(s)] = 0.000e+00 —— Q* ≤ V* 恒成立
//   Hoeffding 指数 −2n·(β/√n)²/(1/(1−γ))² = −2β²(1−γ)²，n 从 1 到 1e5 完全不变
//   β=(1/(1−γ))√(½ln(2|S||A|m/δ)) 使 exp(−2β²(1−γ)²) 恰等于 δ/(2|S||A|m)，
//     双侧 × |S||A|m 次更新 = 0.050000 = δ（机器精度相等）
//   (1−γ)² vs 1−γ²：γ=0.9 差 19 倍，γ=0.99 差 199 倍，γ=0.999 差 1999 倍
//   具体 Q*/V* 例：V*(s)−Q*(s,a) = 0.4544 / 0.1741 / 0.0000
function hoeffExp(beta,g){return -2*beta*beta*Math.pow(1-g,2);}
function betaEB(S,A,m,d,g){return (1/(1-g))*Math.sqrt(0.5*Math.log(2*S*A*m/d));}
function budget(S,A,m){return S*A*m;}

/* ══ L13 片内图 ══════════════════════════════════════════════════════
   整部片共用同一张 (s,a) 计数格（课件 p.13 的「已知集」就画在它上面）。 */
var GX=330, GY=150, GW=26, GH=26, GC=10, GR=4;   /* 10 个状态 × 4 个动作 */

/* (s,a) 计数格。fill(i,j) 返回 0..1 的填充比例，cls(i,j) 给颜色类 */
function saGrid(o){
  var x0=o.x!=null?o.x:GX, y0=o.y!=null?o.y:GY;
  for(var i=0;i<GR;i++)for(var j=0;j<GC;j++){
    var x=x0+j*(GW+6), y=y0+i*(GH+6);
    E.gS.append("rect").attr("class","cellbg "+((o.cls&&o.cls(i,j))||""))
      .attr("x",x).attr("y",y).attr("width",GW).attr("height",GH).attr("rx",3);
    var f=o.fill?o.fill(i,j):0;
    if(f>0)E.gS.append("rect").attr("class","vbar "+((o.bar&&o.bar(i,j))||"g"))
      .attr("x",x+2).attr("y",y+GH-2-(GH-4)*f)
      .attr("width",GW-4).attr("height",(GH-4)*f).attr("rx",2);
  }
  if(o.sLab)note("状态 s →",x0-56,y0+GH/2+5,"sm");
  if(o.aLab)note("↓ 动作 a",x0-52,y0+GH*3,"sm");
}

/* 值的阶梯：一条竖轴上摆几个水平刻度，用来比 V*、V^π、下界 */
function vLadder(items,x1,x2){
  items.forEach(function(it){
    E.gS.append("path").attr("class","axline "+(it.cls||""))
      .attr("d","M"+x1+","+it.y+"L"+x2+","+it.y);
    note(it.label,x2+16,it.y+5,it.cls||"sm");
  });
}

/* Beta(a,b) 密度曲线，画在 [x1,x2]×[yBase-h, yBase] 里 */
function betaCurve(a,b,x1,x2,yBase,h,cls){
  var pts=[],mx=0,v=[];
  for(var i=0;i<=60;i++){var t=i/60;
    var y=Math.pow(t,a-1)*Math.pow(1-t,b-1);
    if(!isFinite(y))y=0; v.push(y); if(y>mx)mx=y;}
  for(var i=0;i<=60;i++)pts.push([x1+(x2-x1)*i/60, yBase-h*(v[i]/(mx||1))]);
  curve(pts,"fit "+(cls||""));
  return pts;
}

